 const[page,setPage]=useState(1),[query,setQuery]=useState(''),params=new URLSearchParams({page:String(page),q:query,all:'0',selected:''}),state=useData('admin/suppliers/'+encodeURIComponent(s.id)+'?'+params,ctx.revision),current=state.data?.request_key===params.toString(),sites:Row[]=current?state.data.sites:[];
